"""Identity-keyed ledger list and paging behavior for the Fields screen.

``FieldList`` rebuilds every row (``remove_children`` + ``mount_all``) on each
data push, which loses row identity and repaints the whole ledger for a single
field change. :class:`LedgerList` keeps row widgets keyed by their canonical
identity instead — control IDs for field entries, status for section headers,
the empty state for "no fields" — so unchanged rows keep their widget identity,
changed rows are updated with ``Static.update``, and only genuinely new or
removed keys are mounted or removed. Grouping and markup come from the shared
``_field_list`` builders, so the screen keeps exactly one rendering convention.

:class:`FieldLedger` adds the operator behaviors that make the screen a real
ledger: page windows sized by the configured ``TUI_MAX_FIELDS`` bound (a page
size, never a retention cap — every canonical field stays reachable), an
all-fields mode that exposes every canonical ID including duplicate labels and
compound children, and a mutually exclusive list/detail view on compact
widths where Enter opens the detail and Escape returns to the list.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable
from dataclasses import dataclass
from typing import TYPE_CHECKING, Final, Protocol, TypeVar, cast

from textual.events import Resize
from textual.widgets import Static

from src.logging import get_logger
from src.tui.commands import notify
from src.tui.nav import SCREEN_RUN
from src.tui.projections.models import FieldProjection
from src.tui.styles import COLOR_MUTED, CSS_SELECTOR_PREFIX, markup
from src.tui.widgets.trace import (
    FieldList,
    FieldListData,
    fields_summary_text,
    visible_field_ids,
)
from src.tui.widgets.trace._field_list import (
    field_entry_markup,
    field_section_markup,
    ordered_visible_fields,
)

if TYPE_CHECKING:
    from textual.widget import Widget
    from textual.widgets import Static as StaticWidget

logger = get_logger(__name__)

#: Width at or below which the list and the selected-field detail become
#: mutually exclusive views (a layout bound, like the other TRACE_* bounds).
COMPACT_MAX_WIDTH: Final[int] = 100

_ENTRY_CLASS: Final[str] = "trace-field-entry"
_SELECTED_ENTRY_CLASS: Final[str] = "trace-field-entry--selected"
_SECTION_CLASS: Final[str] = "trace-field-section"
_SECTION_KEY_PREFIX: Final[str] = "section:"
_EMPTY_KEY: Final[str] = "empty"
_EMPTY_TEXT: Final[str] = markup("Scanning page for fields...", COLOR_MUTED)

#: Scoped styling for the compact list/detail exclusivity. Placed on
#: ``#trace-shell`` so the rules stay inside the screen's own subtree.
LEDGER_CSS: Final[str] = f"""
#{CSS_SELECTOR_PREFIX}trace-shell.fields-compact #trace-inspector {{
    display: none;
}}
#{CSS_SELECTOR_PREFIX}trace-shell.fields-compact #trace-detail {{
    display: none;
}}
#{CSS_SELECTOR_PREFIX}trace-shell.fields-compact.fields-detail-open #trace-detail {{
    display: block;
}}
#{CSS_SELECTOR_PREFIX}trace-shell.fields-compact.fields-detail-open #{CSS_SELECTOR_PREFIX}trace-field-list {{
    display: none;
}}
"""

_WidgetT = TypeVar("_WidgetT")


@dataclass(frozen=True)
class _LedgerRow:
    """One desired render row: stable key, markup, classes, widget name."""

    key: str
    text: str
    classes: str
    name: str | None


@dataclass
class _LedgerState:
    """Widget-identity bookkeeping owned by one :class:`LedgerList`."""

    rows: dict[str, Static] = None  # type: ignore[assignment]
    texts: dict[str, str] = None  # type: ignore[assignment]

    def __post_init__(self) -> None:
        """Replace the sentinel defaults with fresh containers."""
        self.rows = {} if self.rows is None else self.rows
        self.texts = {} if self.texts is None else self.texts


def _desired_rows(value: FieldListData) -> list[_LedgerRow]:
    """Project the ledger data slice into keyed rows.

    Mirrors ``FieldList.to_markup``'s grouping loop but keys each row: fields
    by canonical ``control_id``, section headers by status, the empty state by
    a constant key. Using the same markup builders keeps one rendering
    convention.
    """
    if not value.fields:
        return [_LedgerRow(_EMPTY_KEY, _EMPTY_TEXT, "", None)]
    rows: list[_LedgerRow] = []
    current_status = ""
    for control_id, field_projection in ordered_visible_fields(value.fields):
        if field_projection.status != current_status:
            current_status = field_projection.status
            rows.append(
                _LedgerRow(
                    f"{_SECTION_KEY_PREFIX}{current_status}",
                    field_section_markup(current_status),
                    _SECTION_CLASS,
                    None,
                )
            )
        is_selected = control_id == value.selected_id
        classes = _ENTRY_CLASS
        if is_selected:
            classes = f"{classes} {_SELECTED_ENTRY_CLASS}"
        rows.append(
            _LedgerRow(
                control_id,
                field_entry_markup(control_id, field_projection, is_selected=is_selected),
                classes,
                control_id,
            )
        )
    return rows


class LedgerList(FieldList):
    """FieldList that reuses rows keyed by canonical identity."""

    def watch_data(self, value: FieldListData) -> None:
        """Reconcile children toward *value* without rebuilding the list."""
        self.tooltip = "Fields discovered on the page"
        self._reconcile(value)

    def _reconcile(self, value: FieldListData) -> None:
        """Update, mount, and remove rows by key; order afterwards."""
        desired = _desired_rows(value)
        state = _ledger_state(self)
        ordered: list[StaticWidget] = []
        for row in desired:
            child = state.rows.get(row.key)
            if child is not None and child.parent is self:
                if state.texts.get(row.key) != row.text:
                    child.update(row.text)
            else:
                child = Static(row.text, classes=row.classes, name=row.name)
                state.rows[row.key] = child
                self.mount(child)
            child.set_classes(row.classes)
            state.texts[row.key] = row.text
            ordered.append(child)
        desired_keys = {row.key for row in desired}
        for key in [key for key in state.rows if key not in desired_keys]:
            state.rows.pop(key).remove()
            state.texts.pop(key, None)
        self.call_after_refresh(self._apply_order, ordered)
        if value.selected_id:
            self.call_after_refresh(self._scroll_selected_into_view, value.selected_id)

    def _apply_order(self, desired: list[StaticWidget]) -> None:
        """Restore desired row order after deferred mounts and removals."""
        children = list(self.children)
        if len(children) == len(desired) and all(
            current is wanted for current, wanted in zip(children, desired)
        ):
            return
        for target, child in enumerate(desired):
            current = children.index(child)
            if current == target:
                continue
            reference = target + (1 if current < target else 0)
            if reference < len(children):
                self.move_child(child, before=children[reference])
            else:
                self.move_child(child, after=children[-1])
            children.pop(current)
            children.insert(target, child)


def _ledger_state(widget: LedgerList) -> _LedgerState:
    """Return (lazily creating) the identity bookkeeping for *widget*."""
    state = getattr(widget, "_ledger_state", None)
    if state is None:
        state = _LedgerState()
        widget._ledger_state = state  # type: ignore[attr-defined]
    return state


class _LedgerScreen(Protocol):
    """Screen surface the ledger behaviors read and drive."""

    _field_projections: dict[str, FieldProjection]
    _selected_control_id: str | None
    _page_size: int
    _page_index: int
    _show_all_fields: bool
    _detail_open: bool
    _compact: bool

    @property
    def is_attached(self) -> bool: ...

    @property
    def app(self) -> object: ...

    def query_one(self, selector: str, expect_type: type[_WidgetT]) -> _WidgetT: ...

    def query(self, selector: str) -> Iterable[Widget]: ...

    def action_go_home(self) -> None: ...

    def select_field(self, control_id: str) -> None: ...

    def _push_selected(self, control_id: str) -> None: ...


class FieldLedger:
    """Ledger paging, all-fields mode, compact detail, and Run pinning."""

    def init_ledger_state(self: _LedgerScreen, page_size: int) -> None:
        """Seed ledger page/mode state; called from the screen constructor."""
        self._page_size = max(1, page_size)
        self._page_index = 0
        self._show_all_fields = False
        self._detail_open = False
        self._compact = False

    def _ledger_ordered_ids(self: _LedgerScreen) -> tuple[str, ...]:
        """Return ledger order: grouped defaults or every canonical ID."""
        if self._show_all_fields:
            return tuple(self._field_projections)
        return visible_field_ids(self._field_projections)

    def _ledger_page_slice(
        self: _LedgerScreen,
        ordered: tuple[str, ...],
    ) -> tuple[str, ...]:
        """Return the control IDs on the active page."""
        start = self._page_index * self._page_size
        return ordered[start : start + self._page_size]

    def _ledger_clamp_page(self: _LedgerScreen, ordered: tuple[str, ...]) -> None:
        """Keep the page holding the selected (or pinned) field visible."""
        if not ordered:
            self._page_index = 0
            return
        last_page = max(0, (len(ordered) - 1) // self._page_size)
        self._page_index = min(self._page_index, last_page)
        selected = self._selected_control_id
        if selected is not None and selected in ordered:
            self._page_index = ordered.index(selected) // self._page_size

    def _ledger_page_suffix(self: _LedgerScreen) -> str:
        """Return the ``page x/y`` suffix, or "" when a single page exists."""
        ordered = self._ledger_ordered_ids()
        pages = max(1, -(-len(ordered) // self._page_size))
        if pages <= 1:
            return ""
        return f" · page {self._page_index + 1}/{pages}"

    def _push_list(self: _LedgerScreen) -> None:
        """Push the active page of projections into the ledger list."""
        ordered = self._ledger_ordered_ids()
        self._ledger_clamp_page(ordered)
        page_fields = {
            control_id: self._field_projections[control_id]
            for control_id in self._ledger_page_slice(ordered)
        }
        self.query_one(FieldList).data = FieldListData(
            fields=page_fields,
            selected_id=self._selected_control_id or "",
        )

    def _render_ledger_summary(self: _LedgerScreen) -> None:
        """Render the summary line, including the page indicator."""
        widget = self.query_one(f"{CSS_SELECTOR_PREFIX}trace-summary", Static)
        text = fields_summary_text(self._field_projections)
        widget.update(f"{text}{self._ledger_page_suffix()}")

    def _refresh_ledger(self: _LedgerScreen) -> None:
        """Re-render summary, list page, and detail from current state."""
        if not self.is_attached:
            return
        self._render_ledger_summary()
        self._push_list()
        selected = self._selected_control_id
        if selected is not None and selected in self._field_projections:
            self._push_selected(selected)

    def _set_detail_open(self: _LedgerScreen, open_detail: bool) -> None:
        """Toggle the mutually exclusive compact detail view."""
        self._detail_open = open_detail
        for shell in self.query(f"{CSS_SELECTOR_PREFIX}trace-shell"):
            shell.toggle_class("fields-detail-open", open_detail)
        logger.info(
            "tui.fields.detail_toggled",
            open_detail=open_detail,
            control_id=self._selected_control_id or "",
        )

    def action_toggle_all_fields(self: _LedgerScreen) -> None:
        """Expose every canonical control ID, or return to grouped defaults."""
        self._show_all_fields = not self._show_all_fields
        logger.info(
            "tui.fields.all_fields_toggled",
            show_all=self._show_all_fields,
            field_count=len(self._field_projections),
        )
        self._refresh_ledger()

    def action_field_page(self: _LedgerScreen, delta: int) -> None:
        """Turn the ledger page, keeping the selection on screen."""
        ordered = self._ledger_ordered_ids()
        if not ordered:
            return
        last_page = max(0, (len(ordered) - 1) // self._page_size)
        self._page_index = max(0, min(last_page, self._page_index + delta))
        logger.info(
            "tui.fields.page_changed",
            page=self._page_index + 1,
            pages=last_page + 1,
        )
        page_ids = self._ledger_page_slice(ordered)
        if self._selected_control_id in page_ids or not page_ids:
            self._refresh_ledger()
            return
        self.select_field(page_ids[0])

    def action_close_detail_or_home(self: _LedgerScreen) -> None:
        """Close the compact detail first; otherwise return home."""
        if self._compact and self._detail_open:
            self._set_detail_open(False)
            return
        self.action_go_home()

    def action_pin_field_to_run(self: _LedgerScreen) -> None:
        """Pin the selected field on Run and follow it there."""
        control_id = self._selected_control_id or ""
        if not control_id:
            notify.warn(self, notify.NO_FOCUSED_FIELD)
            return
        pin_field = _run_pin_target(self.app)
        if pin_field is None:
            logger.warning("tui.fields.pin_unavailable", control_id=control_id)
        else:
            pin_field(control_id)
            logger.info("tui.fields.pin_requested", control_id=control_id)
        _switch_to_run(self.app)

    def on_resize(self: _LedgerScreen, event: Resize) -> None:
        """Track compact width for list/detail exclusivity."""
        self._compact = event.size.width <= COMPACT_MAX_WIDTH
        for shell in self.query(f"{CSS_SELECTOR_PREFIX}trace-shell"):
            shell.toggle_class("fields-compact", self._compact)
        if not self._compact and self._detail_open:
            self._set_detail_open(False)


def _run_pin_target(app: object) -> Callable[[str], object] | None:
    """Return the Run screen's pin hook when the recomposition has landed."""
    member: object = getattr(getattr(app, "run_screen", None), "pin_field", None)
    if callable(member):
        return cast("Callable[[str], object]", member)
    return None


def _switch_to_run(app: object) -> None:
    """Switch the app to the Run screen when it exposes a switch action."""
    member: object = getattr(app, "switch_screen", None)
    if callable(member):
        cast("Callable[[str], object]", member)(SCREEN_RUN)


__all__ = [
    "COMPACT_MAX_WIDTH",
    "LEDGER_CSS",
    "FieldLedger",
    "LedgerList",
]

